/**
 * CandlestickChart component - lightweight-charts (v5) candlestick chart with
 * SMA/EMA overlays and a volume histogram. Presentational only; all data comes
 * in via props and range selection just moves the visible window.
 * - Portions generated by AI
 */

import { useEffect, useRef, useState } from 'react';
import {
  createChart,
  CandlestickSeries,
  LineSeries,
  HistogramSeries,
  ColorType,
  CrosshairMode,
  LineStyle,
} from 'lightweight-charts';
import type { IChartApi, IPriceLine, ISeriesApi, Time } from 'lightweight-charts';
import type { CandleBar, CandlesResponse, OverlayKey } from '@/types';
import {
  computeSupportResistance,
  computeVolumeProfile,
  VolumeProfilePrimitive,
} from '@/utils/chartAnalysis';

export type ChartRange = '1M' | '3M' | '6M' | '1Y' | '3Y' | '5Y';

// Conventional trading-chart colors: yellow 20, blue 50, red 200 SMA;
// green 9, magenta 21 EMA.
export const OVERLAY_CONFIG: Record<OverlayKey, { label: string; color: string; lineWidth: number }> = {
  sma_20: { label: 'SMA 20', color: '#facc15', lineWidth: 1 },
  sma_50: { label: 'SMA 50', color: '#3b82f6', lineWidth: 1 },
  sma_200: { label: 'SMA 200', color: '#ef4444', lineWidth: 2 },
  ema_9: { label: 'EMA 9', color: '#34d399', lineWidth: 1 },
  ema_21: { label: 'EMA 21', color: '#e879f9', lineWidth: 1 },
};

const UP_COLOR = '#4ade80'; // green-400
const DOWN_COLOR = '#f87171'; // red-400

function formatVolume(volume: number): string {
  if (volume >= 1e9) return `${(volume / 1e9).toFixed(2)}B`;
  if (volume >= 1e6) return `${(volume / 1e6).toFixed(1)}M`;
  if (volume >= 1e3) return `${(volume / 1e3).toFixed(0)}K`;
  return String(volume);
}

/** OHLC readout line for the hover legend (values are numeric — safe as HTML). */
function hoverHtml(bar: CandleBar): string {
  const up = bar.close >= bar.open;
  const color = up ? '#4ade80' : '#f87171';
  const chg = ((bar.close - bar.open) * 100) / bar.open;
  const num = (v: number) => `<span style="color:${color}">${v.toFixed(2)}</span>`;
  return (
    `<span style="color:rgba(255,255,255,0.45)">${bar.time}</span>` +
    `  O ${num(bar.open)}  H ${num(bar.high)}  L ${num(bar.low)}  C ${num(bar.close)}` +
    ` <span style="color:${color}">${chg >= 0 ? '+' : ''}${chg.toFixed(2)}%</span>` +
    `  Vol <span style="color:rgba(255,255,255,0.75)">${formatVolume(bar.volume)}</span>`
  );
}

const RANGE_MONTHS: Record<ChartRange, number> = {
  '1M': 1,
  '3M': 3,
  '6M': 6,
  '1Y': 12,
  '3Y': 36,
  '5Y': 60,
};

function rangeStart(lastTime: string, range: ChartRange): string {
  const d = new Date(`${lastTime}T00:00:00Z`);
  d.setUTCMonth(d.getUTCMonth() - RANGE_MONTHS[range]);
  return d.toISOString().slice(0, 10);
}

// Widest a daily candle may render; short ranges on wide screens extend the
// window backwards to fill the pane instead of stretching ~22 huge bars.
const MAX_BAR_SPACING = 15;

/** First displayed bar: the selected range, extended backwards on wide panes
 *  so candles never stretch beyond MAX_BAR_SPACING. */
function effectiveStartIndex(
  chart: IChartApi | null,
  data: CandlesResponse,
  range: ChartRange,
  paneWidthOverride?: number
): number {
  const candles = data.candles;
  const last = candles[candles.length - 1].time;
  const from = rangeStart(last, range);
  let startIdx = candles.findIndex((c) => c.time >= from);
  if (startIdx < 0) startIdx = 0;

  const paneWidth = paneWidthOverride ?? chart?.timeScale().width() ?? 0;
  if (paneWidth > 0) {
    const fitBars = Math.floor(paneWidth / MAX_BAR_SPACING);
    if (candles.length - startIdx < fitBars) startIdx = Math.max(0, candles.length - fitBars);
  }
  return startIdx;
}

function applyVisibleRange(
  chart: IChartApi,
  data: CandlesResponse,
  range: ChartRange,
  paneWidthOverride?: number
) {
  const candles = data.candles;
  if (candles.length === 0) return;
  chart.timeScale().setVisibleRange({
    from: candles[effectiveStartIndex(chart, data, range, paneWidthOverride)].time as Time,
    to: candles[candles.length - 1].time as Time,
  });
}

/** Candles in the displayed window (used for profile and S/R so they match
 *  what's on screen, including the wide-pane extension). */
function sliceForRange(chart: IChartApi | null, data: CandlesResponse, range: ChartRange): CandleBar[] {
  if (data.candles.length === 0) return [];
  return data.candles.slice(effectiveStartIndex(chart, data, range));
}

interface CandlestickChartProps {
  data: CandlesResponse;
  range: ChartRange;
  visibleOverlays: Set<OverlayKey>;
  showVolume: boolean;
  showVolumeProfile: boolean;
  showSupportResistance: boolean;
}

export function CandlestickChart({
  data,
  range,
  visibleOverlays,
  showVolume,
  showVolumeProfile,
  showSupportResistance,
}: CandlestickChartProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const overlaySeriesRef = useRef<Partial<Record<OverlayKey, ISeriesApi<'Line'>>>>({});
  const volumeSeriesRef = useRef<ISeriesApi<'Histogram'> | null>(null);
  const candleSeriesRef = useRef<ISeriesApi<'Candlestick'> | null>(null);
  const volumeProfileRef = useRef<VolumeProfilePrimitive | null>(null);
  const priceLinesRef = useRef<IPriceLine[]>([]);
  const hoverRef = useRef<HTMLDivElement>(null);
  const rangeRef = useRef(range);
  rangeRef.current = range;
  // Bumped on container resize so window-dependent overlays recompute
  const [resizeTick, setResizeTick] = useState(0);

  // Create chart + series whenever the dataset changes (i.e. new symbol)
  useEffect(() => {
    const container = containerRef.current;
    if (!container || data.candles.length === 0) return;

    const chart = createChart(container, {
      width: container.clientWidth,
      height: container.clientHeight,
      layout: {
        background: { type: ColorType.Solid, color: '#0f0f1a' },
        textColor: 'rgba(255,255,255,0.55)',
        // The license-required TradingView attribution lives in the panel
        // toolbar instead of on the canvas (see StockChartPanel).
        attributionLogo: false,
      },
      grid: {
        vertLines: { color: 'rgba(255,255,255,0.06)' },
        horzLines: { color: 'rgba(255,255,255,0.06)' },
      },
      crosshair: { mode: CrosshairMode.Normal },
      rightPriceScale: { borderColor: 'rgba(255,255,255,0.1)' },
      // minBarSpacing must be small enough to fit ~1,260 daily bars (5Y) in a
      // ~500px pane; the 0.5 default clamps the visible range to ~4 years.
      timeScale: { borderColor: 'rgba(255,255,255,0.1)', minBarSpacing: 0.1 },
    });
    chartRef.current = chart;

    const volumeSeries = chart.addSeries(HistogramSeries, {
      priceScaleId: 'volume',
      priceFormat: { type: 'volume' },
      priceLineVisible: false,
      lastValueVisible: false,
    });
    chart.priceScale('volume').applyOptions({ scaleMargins: { top: 0.8, bottom: 0 } });
    volumeSeries.setData(
      data.candles.map((c) => ({
        time: c.time as Time,
        value: c.volume,
        color: c.close >= c.open ? 'rgba(74,222,128,0.35)' : 'rgba(248,113,113,0.35)',
      }))
    );
    volumeSeriesRef.current = volumeSeries;

    const candleSeries = chart.addSeries(CandlestickSeries, {
      upColor: UP_COLOR,
      downColor: DOWN_COLOR,
      wickUpColor: UP_COLOR,
      wickDownColor: DOWN_COLOR,
      borderVisible: false,
    });
    candleSeries.setData(data.candles.map((c) => ({ ...c, time: c.time as Time })));
    candleSeriesRef.current = candleSeries;

    const volumeProfile = new VolumeProfilePrimitive();
    candleSeries.attachPrimitive(volumeProfile as never);
    volumeProfileRef.current = volumeProfile;

    // OHLC readout: hovered bar, or the latest bar when not hovering
    const byTime = new Map(data.candles.map((c) => [c.time, c]));
    const lastBar = data.candles[data.candles.length - 1];
    const setHover = (bar: CandleBar) => {
      if (hoverRef.current) hoverRef.current.innerHTML = hoverHtml(bar);
    };
    setHover(lastBar);
    chart.subscribeCrosshairMove((param) => {
      const bar = param.time ? byTime.get(param.time as string) : undefined;
      setHover(bar ?? lastBar);
    });

    overlaySeriesRef.current = {};
    (Object.keys(OVERLAY_CONFIG) as OverlayKey[]).forEach((key) => {
      const points = data.overlays[key];
      if (!points || points.length === 0) return;
      const series = chart.addSeries(LineSeries, {
        color: OVERLAY_CONFIG[key].color,
        lineWidth: OVERLAY_CONFIG[key].lineWidth as 1 | 2,
        priceLineVisible: false,
        lastValueVisible: false,
        crosshairMarkerVisible: false,
      });
      series.setData(points.map((p) => ({ time: p.time as Time, value: p.value })));
      overlaySeriesRef.current[key] = series;
    });

    const observer = new ResizeObserver((entries) => {
      const { width, height } = entries[0].contentRect;
      if (width > 0 && height > 0) {
        chart.applyOptions({ width, height });
        // Resizing preserves bar spacing, not the window — keep the selected
        // range. timeScale().width() is stale here, so derive the pane width
        // from the observed size minus the price axis.
        const paneWidth = width - (chart.priceScale('right').width() || 70);
        applyVisibleRange(chart, data, rangeRef.current, paneWidth);
        setResizeTick((t) => t + 1);
      }
    });
    observer.observe(container);

    return () => {
      observer.disconnect();
      chart.remove();
      chartRef.current = null;
      overlaySeriesRef.current = {};
      volumeSeriesRef.current = null;
      candleSeriesRef.current = null;
      volumeProfileRef.current = null;
      priceLinesRef.current = [];
    };
  }, [data]);

  // Move the visible window when the range changes
  useEffect(() => {
    if (chartRef.current) applyVisibleRange(chartRef.current, data, range);
  }, [data, range]);

  // Toggle overlay visibility without touching data
  useEffect(() => {
    (Object.keys(OVERLAY_CONFIG) as OverlayKey[]).forEach((key) => {
      overlaySeriesRef.current[key]?.applyOptions({ visible: visibleOverlays.has(key) });
    });
  }, [data, visibleOverlays]);

  useEffect(() => {
    volumeSeriesRef.current?.applyOptions({ visible: showVolume });
  }, [data, showVolume]);

  // Volume-by-price shelf, computed over the selected range window
  useEffect(() => {
    const profile = volumeProfileRef.current;
    if (!profile) return;
    profile.setBuckets(
      showVolumeProfile ? computeVolumeProfile(sliceForRange(chartRef.current, data, range)) : []
    );
  }, [data, range, showVolumeProfile, resizeTick]);

  // Support/resistance price lines, recomputed per range window
  useEffect(() => {
    const series = candleSeriesRef.current;
    if (!series) return;
    priceLinesRef.current.forEach((line) => series.removePriceLine(line));
    priceLinesRef.current = [];
    if (!showSupportResistance) return;
    priceLinesRef.current = computeSupportResistance(sliceForRange(chartRef.current, data, range)).map((level) =>
      series.createPriceLine({
        price: level.price,
        color: level.kind === 'support' ? 'rgba(74,222,128,0.6)' : 'rgba(248,113,113,0.6)',
        lineWidth: 1,
        lineStyle: LineStyle.Dashed,
        axisLabelVisible: true,
        title: level.kind === 'support' ? 'S' : 'R',
      })
    );
  }, [data, range, showSupportResistance, resizeTick]);

  return (
    <div className="relative flex-1 min-h-0 w-full">
      <div ref={containerRef} className="absolute inset-0" />
      <div
        ref={hoverRef}
        className="absolute top-2 left-2 z-10 pointer-events-none text-xs font-mono text-gray-300 bg-dark-900/70 px-2 py-1 rounded max-w-[calc(100%-4rem)]"
      />
    </div>
  );
}
